var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.Use(async (context, next) =>
{
    context.Response.Headers["X-Trace"] = "A-in";
    await next();
    context.Response.Headers["X-Trace"] += ",A-out";
});

app.Use(async (context, next) =>
{
    context.Response.Headers["X-Trace"] += ",B-in";
    await next();
    context.Response.Headers["X-Trace"] += ",B-out";
});

app.MapGet("/ping", () => "pong");

app.Run();
// Response header: A-in,B-in,B-out,A-out

app.Use(async (context, next) =>
{
    var sw = Stopwatch.StartNew();
    try
    {
        await next();
    }
    finally
    {
        sw.Stop();
        context.Response.Headers["X-Elapsed-Ms"] = sw.ElapsedMilliseconds.ToString();
    }
});

// Conceptually, app.Use calls build a linked list:
// RequestDelegate pipeline =
//   mwA(context => mwB(context => mwC(context => endpoint)));
//
// mwA: run pre → call inner → run post
// No magic thread — single async call stack per request

app.Lifetime.ApplicationStarted.Register(() =>
{
    var logger = app.Services.GetRequiredService<ILoggerFactory>()
        .CreateLogger("Pipeline");
    logger.LogInformation("Pipeline built — verify Use* order in Program.cs");
});
